function range30d() {
  const endAt = Date.now();
  const startAt = endAt - 30 * 24 * 60 * 60 * 1000;
  return { startAt, endAt };
}

function qs(params) {
  return new URLSearchParams(
    Object.entries(params).map(([k, v]) => [k, String(v)])
  ).toString();
}

function apiBases() {
  const region = (process.env.REACT_APP_UMAMI_API_REGION || "eu").toLowerCase();
  const list = [
    process.env.REACT_APP_UMAMI_API_URL,
    region ? `https://api.umami.is/v1/${region}` : null,
    "https://api.umami.is/v1/eu",
    "https://api.umami.is/v1/us",
    "https://api.umami.is/v1",
  ].filter(Boolean);
  return [...new Set(list.map((b) => b.replace(/\/$/, "")))];
}

async function tryFetch(url, apiKey) {
  const res = await fetch(url, {
    headers: {
      Accept: "application/json",
      "x-umami-api-key": apiKey,
    },
  });
  if (!res.ok) return null;
  return res.json();
}

async function umamiGet(path, apiKey, params = {}) {
  const query = qs({ ...range30d(), ...params });
  for (const base of apiBases()) {
    const url = `${base}${path}?${query}`;
    try {
      const data = await tryFetch(url, apiKey);
      if (data != null) return data;
    } catch {
      /* try next base */
    }
  }
  throw new Error("umami_unreachable");
}

export function getWebsiteId() {
  return (
    process.env.REACT_APP_UMAMI_WEBSITE_ID ||
    "be0902b7-eca2-4d8e-a436-5ade90cca757"
  );
}

export function getShareUrl() {
  return process.env.REACT_APP_UMAMI_SHARE_URL || "";
}

export function getApiKey() {
  return process.env.REACT_APP_UMAMI_API_KEY || "";
}

export async function fetchWebsiteStats(apiKey, websiteId) {
  return umamiGet(`/websites/${websiteId}/stats`, apiKey);
}

export async function fetchActive(apiKey, websiteId) {
  try {
    return await umamiGet(`/websites/${websiteId}/active`, apiKey);
  } catch {
    return { visitors: 0 };
  }
}

export async function fetchMetrics(apiKey, websiteId, type, limit = 10) {
  return umamiGet(`/websites/${websiteId}/metrics`, apiKey, { type, limit });
}

export async function fetchAllStats(apiKey, websiteId) {
  const [summary, active, countries, pages] = await Promise.all([
    fetchWebsiteStats(apiKey, websiteId),
    fetchActive(apiKey, websiteId),
    fetchMetrics(apiKey, websiteId, "country", 12),
    fetchMetrics(apiKey, websiteId, "path", 10),
  ]);
  return { summary, active, countries, pages };
}
