import { useEffect, useState } from "react";
import { fetchAllStats, getApiKey, getWebsiteId } from "../lib/umamiApi";

export function useUmamiStats() {
  const [state, setState] = useState({
    loading: Boolean(getApiKey()),
    error: null,
    summary: null,
    active: null,
    countries: [],
    pages: [],
  });

  useEffect(() => {
    const apiKey = getApiKey();
    const websiteId = getWebsiteId();

    if (!apiKey) {
      setState((s) => ({ ...s, loading: false, error: "no_api_key" }));
      return;
    }

    let cancelled = false;

    (async () => {
      try {
        const data = await fetchAllStats(apiKey, websiteId);
        if (cancelled) return;
        setState({
          loading: false,
          error: null,
          summary: data.summary,
          active: data.active,
          countries: Array.isArray(data.countries) ? data.countries : [],
          pages: Array.isArray(data.pages) ? data.pages : [],
        });
      } catch {
        if (cancelled) return;
        setState({
          loading: false,
          error: "fetch_failed",
          summary: null,
          active: null,
          countries: [],
          pages: [],
        });
      }
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  return state;
}
